#include "icon_assets.hpp"

#include <array>

// Each is generated by cmake/EmbedFile.cmake from app/assets/icon/<colour>/ (app/CMakeLists.txt).
namespace etude::app {
std::span<const unsigned char> embedded_icon_wine_256();
std::span<const unsigned char> embedded_icon_wine_64();
std::span<const unsigned char> embedded_icon_teal_256();
std::span<const unsigned char> embedded_icon_teal_64();
std::span<const unsigned char> embedded_icon_petrol_256();
std::span<const unsigned char> embedded_icon_petrol_64();
std::span<const unsigned char> embedded_icon_cobalt_256();
std::span<const unsigned char> embedded_icon_cobalt_64();
std::span<const unsigned char> embedded_icon_midnight_256();
std::span<const unsigned char> embedded_icon_midnight_64();
std::span<const unsigned char> embedded_icon_aubergine_256();
std::span<const unsigned char> embedded_icon_aubergine_64();
std::span<const unsigned char> embedded_icon_graphite_256();
std::span<const unsigned char> embedded_icon_graphite_64();
std::span<const unsigned char> embedded_icon_black_256();
std::span<const unsigned char> embedded_icon_black_64();

std::span<const unsigned char> icon_png(etude::IconColour colour, int px) {
    struct Pair {
        std::span<const unsigned char> big;
        std::span<const unsigned char> small;
    };
    // In the order of etude::kIconColours.
    const std::array<Pair, etude::kIconColourCount> pairs{{
    {embedded_icon_wine_256(), embedded_icon_wine_64()},
    {embedded_icon_teal_256(), embedded_icon_teal_64()},
    {embedded_icon_petrol_256(), embedded_icon_petrol_64()},
    {embedded_icon_cobalt_256(), embedded_icon_cobalt_64()},
    {embedded_icon_midnight_256(), embedded_icon_midnight_64()},
    {embedded_icon_aubergine_256(), embedded_icon_aubergine_64()},
    {embedded_icon_graphite_256(), embedded_icon_graphite_64()},
    {embedded_icon_black_256(), embedded_icon_black_64()},
    }};
    const Pair& pair = pairs[static_cast<std::size_t>(colour)];
    return px == 64 ? pair.small : pair.big;
}

} // namespace etude::app
